INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(12790, 'plPL', 'Jak wyjść i wrócić – sposób magiczny', 'Gdybyś jeszcze nie $gwiedział:wiedziała;: kryształem na platformie za mną możesz się teleportować do Purpurowej Reduty w Lesie Kryształowej Pieśni, pod Dalaranem.$B$BAnalogicznie kryształem w reducie na dole wrócisz do komnaty nade mną.$B$BChciałabym, żebyś $gzrobił:zrobiła; to teraz.', 'Arcymagini Celindra przy Purpurowej Bramie w Dalaranie chce, żebyś $gużył:użyła; Kryształu teleportacji do Purpurowej Reduty i Kryształu teleportacji do Dalaranu.', '', 'Wróć do arcymagini Celindry przy Purpurowej Bramie w Dalaranie.', 'Użyto Kryształu teleportacji do Purpurowej Reduty', 'Użyto Kryształu teleportacji do Dalaranu', '', '', 0),
(12958, 'plPL', 'Dostawa: Amulet z krwawego nefrytu', 'Pewna zamożna firma przewozowa zamówiła partię amuletów z krwawego nefrytu na sprzedaż w Undermine. Jeśli przyniesiesz mi jeden, nagrodzę cię Dalarańskim żetonem jubilerskim.$B', 'Połącz wrykulski amulet, ciemny nefryt i krwawnik, by wykonać amulet z krwawego nefrytu, i zanieś go Timothy\'emu Jonesowi w Dalaranie.$B$BWrykulski amulet zdobędziesz od dowolnego wrykula w Północnej Grani.', '', 'Wróć do Timothy\'ego Jonesa w sklepie „Cartier i S-ka – Wykwintna Biżuteria” w Dalaranie.', '', '', '', '', 0),
(12959, 'plPL', 'Dostawa: Jarząca się figurka z kości słoniowej', 'Pewna zamożna firma przewozowa zamówiła partię jarzących się figurek z kości słoniowej na sprzedaż w Undermine. Jeśli przyniesiesz mi jedną, nagrodzę cię Dalarańskim żetonem jubilerskim.$B', 'Połącz północną kość słoniową, chalcedon i kryształ cienia, by wykonać jarzącą się figurkę z kości słoniowej, i zanieś ją Timothy\'emu Jonesowi w Dalaranie.$B$BPółnocną kość słoniową zdobędziesz od dowolnego łopatokła lub mamuta w Północnej Grani.', '', 'Wróć do Timothy\'ego Jonesa w sklepie „Cartier i S-ka – Wykwintna Biżuteria” w Dalaranie.', '', '', '', '', 0),
(12960, 'plPL', 'Dostawa: Broszka nikczemnego słońca', 'Pewna zamożna firma przewozowa zamówiła partię broszek nikczemnego słońca na sprzedaż w Undermine. Jeśli przyniesiesz mi jedną, nagrodzę cię Dalarańskim żetonem jubilerskim.$B', 'Połącz broszkę żelaznych krasnoludów, ogromny cytryn i kryształ słońca, by wykonać broszkę nikczemnego słońca, i zanieś ją Timothy\'emu Jonesowi w Dalaranie.$B$BBroszkę żelaznych krasnoludów zdobędziesz od dowolnego żelaznego krasnoluda w Północnej Grani.', '', 'Wróć do Timothy\'ego Jonesa w sklepie „Cartier i S-ka – Wykwintna Biżuteria” w Dalaranie.', '', '', '', '', 0),
(12961, 'plPL', 'Dostawa: Misterna figurka z kości', 'Pewna zamożna firma przewozowa zamówiła partię misternych figurek z kości na sprzedaż w Undermine. Jeśli przyniesiesz mi jedną, nagrodzę cię Dalarańskim żetonem jubilerskim.$B', 'Połącz kość protosmoka, kryształ słońca i ciemny nefryt, by wykonać misterną figurkę z kości, i zanieś ją Timothy\'emu Jonesowi w Dalaranie.$B$BKość protosmoka zdobędziesz od dowolnego protosmoka w Północnej Grani.', '', 'Wróć do Timothy\'ego Jonesa w sklepie „Cartier i S-ka – Wykwintna Biżuteria” w Dalaranie.', '', '', '', '', 0),
(12962, 'plPL', 'Dostawa: Relikwia jasnej zbroi', 'Pewna zamożna firma przewozowa zamówiła partię relikwii jasnej zbroi na sprzedaż w Undermine. Jeśli przyniesiesz mi jedną, nagrodzę cię Dalarańskim żetonem jubilerskim.$B', 'Połącz skrawek pancerza żywiołów, krwawnik i ogromny cytryn, by wykonać relikwię jasnej zbroi, i zanieś ją Timothy\'emu Jonesowi w Dalaranie.$B$BSkrawek pancerza żywiołów zdobędziesz od dowolnej zjawy w Północnej Grani.', '', 'Wróć do Timothy\'ego Jonesa w sklepie „Cartier i S-ka – Wykwintna Biżuteria” w Dalaranie.', '', '', '', '', 0),
(12963, 'plPL', 'Dostawa: Zmienne słoneczne cacko', 'Pewna zamożna firma przewozowa zamówiła partię zmiennych słonecznych cacek na sprzedaż w Undermine. Jeśli przyniesiesz mi jedno, nagrodzę cię Dalarańskim żetonem jubilerskim.$B', 'Połącz osobliwość Plagi, kryształ słońca i kryształ cienia, by wykonać zmienne słoneczne cacko, i zanieś je Timothy\'emu Jonesowi w Dalaranie.$B$BOsobliwość Plagi zdobędziesz od dowolnego sługi Plagi w Północnej Grani.', '', 'Wróć do Timothy\'ego Jonesa w sklepie „Cartier i S-ka – Wykwintna Biżuteria” w Dalaranie.', '', '', '', '', 0),
(13041, 'plPL', 'Dokończ dostawę', 'Dobrze, że jesteś! Partia jarzących się figurek z kości słoniowej musi natychmiast wyruszyć do Undermine, a wciąż brakuje mi chalcedonu na oko do ostatniej z nich.$B$BPrzynieś mi jeden, a dalarański żeton jubilerski będzie twój.', 'Przynieś chalcedon Timothy\'emu Jonesowi w Dalaranie.', '', 'Wróć do Timothy\'ego Jonesa w sklepie „Cartier i S-ka – Wykwintna Biżuteria” w Dalaranie.', '', '', '', '', 0),
(13100, 'plPL', 'Pieczeń z nasączonymi grzybami', 'Mamy ważne zamówienie do wysłania! Orton Bennet ze sklepu „Osobliwości i Moore” potrzebuje pieczeni z grzybami.$B$BZdobądź nasączone grzyby, które rosną w kanałach Dalaranu, i schłodzone mięso, a potem upiecz je w tej formie do pieczeni. Kiedy skończysz, zanieś gotową pieczeń Ortonowi.', 'Przyrządź w formie do pieczeni 4 nasączone grzyby i 2 porcje schłodzonego mięsa, a gotową pieczeń z grzybami zanieś Ortonowi Bennetowi do sklepu „Osobliwości i Moore” na Placu Runotkaczy w Dalaranie.', '', 'Porozmawiaj z Ortonem Bennetem w sklepie „Osobliwości i Moore” w Dalaranie.', '', '', '', '', 0),
(13101, 'plPL', 'Zjazd w salonie „Prestidigitator”', 'Arille Lazurowe Spojrzenie z salonu „Prestidigitator” spodziewa się gości na zjeździe i potrzebuje uczty, i to migiem!$B$BMusisz dostarczyć trochę północnego gulaszu i dzban wina ze sklepu z serami „Jeszcze Jeden Kieliszek” w centrum Dalaranu. Właściciel sklepu jest mi winien to wino, powinno stać gdzieś w sklepie.$B$BZanieś wino i gulasz Arille\'owi.', 'Przynieś Arille\'owi Lazurowemu Spojrzeniu do salonu „Prestidigitator” na Placu Runotkaczy w Dalaranie 4 porcje północnego gulaszu, które przyrządzisz dzięki umiejętności gotowania, oraz dzban wina ze sklepu z serami w Dalaranie.', '', 'Porozmawiaj z Arille\'em Lazurowym Spojrzeniem w salonie „Prestidigitator” w Dalaranie.', '', '', '', '', 0),
(13102, 'plPL', 'Kanałowy gulasz', 'Ajay Green, karczmarz w kanałach Dalaranu, potrzebuje gulaszu warzywnego dla swoich gości, bo kończy im się tam na dole jedzenie.$B$BZbierz 4 marchewki z Kryształowej Pieśni w Lesie Kryształowej Pieśni i ugotuj je razem z 4 porcjami schłodzonego mięsa.$B$BDo Lasu Kryształowej Pieśni dostaniesz się z komnaty portali we wschodnim rogu Placu Runotkaczy.$B$BKiedy gulasz warzywny będzie gotowy, zanieś go Ajayowi.', 'Ugotuj w kociołku 4 marchewki z Kryształowej Pieśni z Lasu Kryształowej Pieśni i 4 porcje schłodzonego mięsa.$B$BGdy gulasz warzywny będzie gotowy, zanieś go karczmarzowi z kanałów Dalaranu, Ajayowi Greenowi.', '', 'Porozmawiaj z Ajayem Greenem w „Sztuczkach i Wronach” w Dalaranie.', '', '', '', '', 0),
(13103, 'plPL', 'Ser dla Glowergolda', 'Ranid Glowergold ze sklepu kaletniczego w Dalaranie nabrał nagłej ochoty na wino i ser.$B$BWeź ser z półki w sklepie „Jeszcze Jeden Kieliszek” w centrum Dalaranu i zbierz do połowy pełne kieliszki wina, które stoją na stołach w całym mieście. Zlej wino do jednej butelki i podaj je Ranidowi razem z serem.$B$BRaczej nie zauważy różnicy.', 'Połącz pusty półmisek na ser z dojrzałym dalarańskim limburgerem ze sklepu z serami „Jeszcze Jeden Kieliszek” i z 6 do połowy pełnymi kieliszkami dalarańskiego wina, które stoją na stołach w Dalaranie.$B$BZanieś półmisek wina i sera Ranidowi Glowergoldowi do sklepu kaletniczego na Giełdzie Handlowej Magów.', '', 'Porozmawiaj z Ranidem Glowergoldem w sklepie „Legendarne Skóry” w Dalaranie.', '', '', '', '', 0),
(13107, 'plPL', 'Hot dogi z musztardą!', 'Arcymag Pentarus lubi od czasu do czasu obejrzeć mecz bitewnej piłki i właśnie się na niego wybiera, ale potrzebuje prowiantu na drogę.$B$BMusisz napełnić jego koszyk piknikowy 4 hot dogami z nosorożca, które przyrządzisz, i 4 garściami dzikiej gorczycy, która rośnie na trawiastych skrawkach miasta.$B$BZanieś mu koszyk piknikowy, żeby był gotowy na wielki mecz.', 'Napełnij pusty koszyk piknikowy 4 hot dogami z nosorożca, które przyrządzisz dzięki umiejętności gotowania, i 4 garściami dzikiej gorczycy z trawiastych skrawków Dalaranu.$B$BZanieś koszyk piknikowy arcymagowi Pentarusowi na Przystań Krasusa w Dalaranie.', '', 'Porozmawiaj z arcymagiem Pentarusem na Przystani Krasusa w Dalaranie.', '', '', '', '', 0),
(13112, 'plPL', 'Pieczeń z nasączonymi grzybami', 'Orton Bennet ze sklepu „Osobliwości i Moore” chce pieczeń z grzybami.$B$BZdobądź se nasączone grzyby z kanałów Dalaranu i schłodzone mięso, i upiecz to w formie do pieczeni. Jak skończysz, zanieś tę pieczeń Ortonowi.$B$BGdyby tylko rada pozwoliła mi podawać moją gnomią specjalność, to bym im pokazał prawdziwy przysmak!', 'Przyrządź w formie do pieczeni 4 nasączone grzyby i 2 porcje schłodzonego mięsa, a gotową pieczeń z grzybami zanieś Ortonowi Bennetowi do sklepu „Osobliwości i Moore” na Placu Runotkaczy w Dalaranie.', '', 'Porozmawiaj z Ortonem Bennetem w sklepie „Osobliwości i Moore” w Dalaranie.', '', '', '', '', 0),
(13113, 'plPL', 'Zjazd w salonie „Prestidigitator”', 'Uwierzysz, że Horda zakazała kanibalizmu...? To nie w porządku, mówię ci! No, chyba lepiej myśleć o robocie, jak jest zamówienie do zrobienia.$B$BDo Arille\'a Lazurowego Spojrzenia z salonu „Prestidigitator” zjeżdża kupa gości, mon. Musisz załatwić trochę północnego gulaszu i dzban wina ze sklepu z serami w centrum Dalaranu.$B$BZanieś wino i gulasz Arille\'owi.', 'Przynieś Arille\'owi Lazurowemu Spojrzeniu do salonu „Prestidigitator” na Placu Runotkaczy w Dalaranie 4 porcje północnego gulaszu i dzban wina ze sklepu z serami w Dalaranie.', '', 'Porozmawiaj z Arille\'em Lazurowym Spojrzeniem w salonie „Prestidigitator” w Dalaranie.', '', '', '', '', 0),
(13114, 'plPL', 'Kanałowy gulasz', 'Mamy kolejne zamówienie. Karczmarz w kanałach Dalaranu potrzebuje gulaszu warzywnego, bo jego goście nie mają za dużo do jedzenia, mon.$B$BPoprosił o gulasz warzywny, bo nie spodobał mu się gnom w poprzednim gulaszu, co mu wysłałem. Zdobądź 4 marchewki z Kryształowej Pieśni w Lesie Kryształowej Pieśni, ugotuj je z 4 porcjami schłodzonego mięsa i zanieś to Ajayowi.$B$BDo Lasu dostaniesz się z komnaty portali we wschodnim rogu Placu Runotkaczy.', 'Ugotuj w kociołku 4 marchewki z Kryształowej Pieśni z Lasu Kryształowej Pieśni i 4 porcje schłodzonego mięsa.$B$BNastępnie zanieś gulasz warzywny karczmarzowi z kanałów Dalaranu, Ajayowi Greenowi.', '', 'Porozmawiaj z Ajayem Greenem w „Sztuczkach i Wronach” w Dalaranie.', '', '', '', '', 0),
(13115, 'plPL', 'Ser dla Glowergolda', 'Ranid Glowergold ze sklepu kaletniczego potrzebuje wina i sera. Czemu nie chce smacznego gnoma, tego nie pojmę.$B$BWeź ser ze sklepu z serami w centrum Dalaranu i zbierz do połowy pełne kieliszki wina ze stołów w całym mieście. Zanieś wino i podaj je Ranidowi z serem.$B$BMożesz nazwać to wino Mieszanką Win, mon.', 'Połącz pusty półmisek na ser z dojrzałym dalarańskim limburgerem ze sklepu z serami „Jeszcze Jeden Kieliszek” i z 6 do połowy pełnymi kieliszkami dalarańskiego wina, które stoją na stołach w Dalaranie.$B$BZanieś półmisek wina i sera Ranidowi Glowergoldowi do sklepu kaletniczego na Giełdzie Handlowej Magów.', '', 'Porozmawiaj z Ranidem Glowergoldem w sklepie „Legendarne Skóry” w Dalaranie.', '', '', '', '', 0),
(13116, 'plPL', 'Hot dogi z musztardą!', 'Arcymag Pentarus lubi oglądać tę swoją zwariowaną bitewną piłkę, ale potrzebuje jedzenia na mecz.$B$BMusisz napełnić jego koszyk piknikowy 4 upieczonymi hot dogami z nosorożca i 4 garściami dzikiej gorczycy, co rośnie w trawiastych zakątkach miasta.$B$BNapełnij mu koszyk tymi musztardowymi pysznościami, mon.', 'Napełnij pusty koszyk piknikowy 4 hot dogami z nosorożca, które przyrządzisz dzięki umiejętności gotowania, i 4 garściami dzikiej gorczycy z trawiastych skrawków Dalaranu.$B$BZanieś koszyk piknikowy arcymagowi Pentarusowi na Przystań Krasusa w Dalaranie.', '', 'Porozmawiaj z arcymagiem Pentarusem na Przystani Krasusa w Dalaranie.', '', '', '', '', 0),
(13148, 'plPL', 'Naprawa naszyjnika', 'Do uszkodzonego naszyjnika dołączona jest faktura z napisem: „Własność Timothy\'ego Jonesa – Cartier i S-ka, Wykwintna Biżuteria – Giełda Handlowa Magów – Dalaran”.$B$BMoże warto go naprawić i zwrócić właścicielowi.$B', 'Napraw naszyjnik za pomocą jednego chalcedonu i zwróć go Timothy\'emu Jonesowi w sklepie jubilerskim na Giełdzie Handlowej Magów w Dalaranie.', '', 'Wróć do Timothy\'ego Jonesa w sklepie „Cartier i S-ka – Wykwintna Biżuteria” w Dalaranie.', '', '', '', '', 0),
(13158, 'plPL', 'Dyskrecja przede wszystkim', 'Posłuchaj mnie uważnie.$b$bWłaśnie doniesiono mi o incydencie w Purpurowej Twierdzy. Wygląda na to, że błękitne smoki przypuszczają zmasowaną inwazję na Dalaran!$b$bMusisz natychmiast udać się do więzienia i porozmawiać ze strażnikiem Alturasem. On przekaże ci szczegóły.$b$bTo nie wszystko. Ta sprawa wymaga najwyższej dyskrecji. Nie wolno nam niepokoić mieszkańców Dalaranu, jeśli tylko da się tego uniknąć. Czy wyrażam się jasno?$b$bDobrze. A teraz idź!', 'Rhonin chce, żebyś $gudał:udała; się do Purpurowej Twierdzy w Dalaranie i $gporozmawiał:porozmawiała; ze strażnikiem Alturasem.', '', '', '', '', '', '', 0),
(13159, 'plPL', 'Powstrzymanie', 'Oto klucz do więzienia.$b$bMoi ludzie i ja zostaniemy tutaj jako ostatnia linia obrony, na wypadek gdyby nie udało ci się odeprzeć ataku.$b$bKoniecznie porozmawiaj z porucznik Sinclari. Ona da ci dostęp do zabezpieczeń więzienia.$b$bPospiesz się. Mamy mało czasu. Tych kilku, których zostawiłem w środku, długo nie wytrzyma bez twojej pomocy. Wróć do mnie, gdy siły najeźdźców zostaną rozbite.', 'Strażnik Alturas chce, żebyś $gwszedł:weszła; do Purpurowej Twierdzy i $gpołożył:położyła; kres inwazji błękitnych smoków. Masz wrócić do niego, gdy Cyjanigosa zginie.', '', 'Wróć do strażnika Alturasa w Purpurowej Twierdzy w Dalaranie.', 'Zabito Cyjanigosę', '', '', '', 0),
(13571, 'plPL', 'Rzeczy znalezione w „Strzałach i łukach”', '', '', '', '', '', '', '', '', 0),
(13631, 'plPL', 'Wszystko dobre, co się dobrze kończy', 'Musimy się teraz pospieszyć, $N. Kod odpowiedzi trzeba będzie nadać z Dalaranu.$B$BZanieś go Rhoninowi, spotkamy się na miejscu.', 'Zanieś kod odpowiedzi alfa Rhoninowi w Dalaranie.', '', 'Wróć do Rhonina w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13819, 'plPL', 'Heroiczne: Wszystko dobre, co się dobrze kończy', 'Musimy się teraz pospieszyć, $N. Kod odpowiedzi trzeba będzie nadać z Dalaranu.$B$BZanieś go Rhoninowi, spotkamy się na miejscu.', 'Zanieś kod odpowiedzi alfa Rhoninowi w Dalaranie.', '', 'Wróć do Rhonina w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13830, 'plPL', 'Widmoryba', 'Każdy wędkarz w Północnej Grani, który zna się na rzeczy, wie o karłowatej podnawce. Nie nadaje się do jedzenia, ale czasem przydaje się alchemikom.$b$bJest jednak pewna skryta ryba, która chowa się wśród podnawek w Sercu Rzeki w Kotlinie Sholazar. Upiorna widmoryba. Wyjęta z wody staje się coraz bardziej przejrzysta, aż w końcu całkiem znika. Niektórzy przypuszczają, że wraca do Sholazar, inni są bardziej... przesądni.$b$bChcę, żebyś $gzłowił:złowiła; tę rybę i za wszelką cenę $godkrył:odkryła; jej sekret!', 'Marcia Chase w Mieście Dalaran chce, żebyś $godkrył:odkryła; tajemnicę upiornej widmoryby.', 'Odkryj tajemnicę widmoryby', 'Wróć do Marcii Chase w Dalaranie.', '', '', '', '', 0),
(13832, 'plPL', 'Klejnot kanałów', 'Trudno uwierzyć, że większość ludzi łowi w Kanałach Dalaranu olbrzymie szczury i zmutowane ryby. Zwłaszcza że te wody pełne są bezcennej biżuterii – wyrzuconej przez głupców ze złamanym sercem, złodziei i nieostrożnych pijaków.$b$bCała sztuka polega na tym, żeby haczyk wlókł się po dnie i żeby nie szarpać za mocno, gdy coś złapiesz. Spróbuj, $N. Chętnie wymienię to, co znajdziesz, na kilka moich drobiazgów.', 'Marcia Chase w Mieście Dalaran chce, żebyś $gprzyniósł:przyniosła; jej sztukę skorodowanej biżuterii.', '', 'Wróć do Marcii Chase w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13833, 'plPL', 'Krew nie woda', 'Krwawozęby szałowiec to zadziorna rybka, której używa się w recepturze na leczenie zakażonych ran. Przydałoby nam się ich trochę, jeśli dasz radę.$b$bJak sama nazwa wskazuje, łakną krwi. Jedyny znany mi sposób na złowienie tych małych diabełków to stworzenie krwawej plamy i łowienie w niej.$b$bUmaż się we krwi – wystarczy zarżnąć jakieś zwierzę w Boreańskiej Tundrze – a potem wskocz do wody. Krew od razu się zmyje i powstanie idealne łowisko.', 'Marcia Chase w Mieście Dalaran chce, żebyś $gprzyniósł:przyniosła; jej 5 krwawozębych szałowców.', '', 'Wróć do Marcii Chase w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13834, 'plPL', 'Niebezpiecznie smaczne', 'Najlepsze łowiska bywają najniebezpieczniejsze. Zimościsk oferuje obfity połów dla zuchwałych.$b$bTo zresztą jedyne miejsce, gdzie można złowić legendarną strachorybę – rybę równie zabójczą, co pyszną. Przynieś mi kilka, a będzie o czym porozmawiać.', 'Marcia Chase w Mieście Dalaran chce, żebyś $gprzyniósł:przyniosła; jej 10 strachoryb.', '', 'Wróć do Marcii Chase w Opuszczonym Lesie w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(13836, 'plPL', 'Rozbrojony!', 'Doszły mnie słuchy o niefortunnym wypadku w dalarańskim więzieniu: wyjątkowo brutalny więzień odciął strażnikowi ramię i wrzucił je do wody.$b$bNasz punkt pierwszej pomocy obiecuje, że przyszyje ramię z powrotem, jeśli je przyniesiemy.$b$bŁów wystarczająco długo w wodzie przed więzieniem, a założę się o moją ulubioną wędkę, że to ramię wypłynie. Znajdź je i zanieś do Olisarry Dobrotliwej tutaj, w Dalaranie. Ona będzie wiedziała, co zrobić.', 'Olisarra Dobrotliwa w Mieście Dalaran chce, żebyś $gprzyniósł:przyniosła; jej odcięte ramię.', '', 'Wróć do Olisarry Dobrotliwej w punkcie „Pierwsi z Pomocą” w Mieście Dalaran.', '', '', '', '', 0),
(13845, 'plPL', 'Zapieczętowana fiolka trucizny', 'Ta fiolka trucizny wygląda na szczególnie niebezpieczną. Może ktoś w Dalaranie byłby nią zainteresowany.', 'Zanieś zapieczętowaną fiolkę trucizny alchemikowi Cinesrze w Kanałach Dalaranu.', '', 'Wróć do alchemika Cinesry na Czarnym Rynku w Dalaranie.', '', '', '', '', 0),
(13959, 'plPL', 'Powrót do sierocińca', 'My się z tobą najlepiej bawić, $N. My chcieć, żebyś teraz $gbył naszym tatą:była naszą mamą;, ale ty musieć nas odprowadzić do opiekunki sierocińca Arii w Dalaranie.$B$BMoże ty nas jeszcze kiedyś odwiedzić? My bardzo lubić poznać młode Zimopłetwych i zobaczyć królową smoków. Nikt nam nie uwierzyć, jak my powiedzieć, że spotkać Wielkiego!$B$BMy za tobą tęsknić, $N. My obiecać kiedyś napisać list, oki?', 'Odprowadź swojego podopiecznego do sierocińca w Dalaranie, oddając gwizdek sieroty wyroczni opiekunce sierocińca Arii w Dalaranie.', '', 'Wróć do opiekunki sierocińca Arii w Dalaranie.', '', '', '', '', 0),
(13960, 'plPL', 'Powrót do sierocińca', 'Wiesz co? Ty jednak nie $gtaki zły:taka zła;, $N. Ty zabrać Kekeka w dużo fajnych miejsc. Kekek poznać dużo nowych przyjaciół i robić rzeczy, których nie robić żaden inny szczeniak.$B$BTy, i Hemet Nesingwary, i szczeniaki z Polany Śniegospadu – wszyscy nowi najlepsi przyjaciele. Może kiedyś ty przynieść Kekekowi tę książkę o zielonych wzgórzach? Kekek obiecać też czasem pisać, opowiedzieć, jak leci. Może nawet czasem być miły dla dzieciaków wielkojęzorów.$B$BKekek musieć teraz wracać do pani od sierot, Arii, do fioletowego miasta ludzi.', 'Odprowadź swojego podopiecznego do sierocińca w Dalaranie, oddając gwizdek sieroty wolvarów opiekunce sierocińca Arii w Dalaranie.', '', 'Wróć do opiekunki sierocińca Arii w Dalaranie.', '', '', '', '', 0),
(14119, 'plPL', '', '', '', '', 'Wróć do Linzy Czarnośrub przy Żelaznej Tamie w Lodowej Koronie.', '', '', '', '', 0),
(14147, 'plPL', '', '', '', '', 'Wróć do Linzy Czarnośrub przy Żelaznej Tamie w Lodowej Koronie.', '', '', '', '', 0),
(14148, 'plPL', '', '', '', '', 'Wróć do Linzy Czarnośrub przy Żelaznej Tamie w Lodowej Koronie.', '', '', '', '', 0),
(14149, 'plPL', '', '', '', '', 'Wróć do Linzy Czarnośrub przy Żelaznej Tamie w Lodowej Koronie.', '', '', '', '', 0),
(14150, 'plPL', '', '', '', '', 'Wróć do Linzy Czarnośrub przy Żelaznej Tamie w Lodowej Koronie.', '', '', '', '', 0),
(14151, 'plPL', 'Kardynalski rubin', 'Mówi się, że kardynalski rubin to najwspanialszy klejnot w całej Północnej Grani. Lśni w słońcu jak kryształowa róża.$b$bZanim nauczę cię tej receptury, proszę, byś $gwykonał:wykonała; pięć transmutacji epickich klejnotów, aby przygotować umysł. Możesz wybrać dowolne, a nawet wielokrotnie powtarzać tę samą transmutację.$b$bWróć do mnie, gdy będziesz naprawdę $ggotów:gotowa;.', 'Linzy Czarnośrub w Dalaranie chce, żebyś za pomocą umiejętności alchemii $gprzeprowadził:przeprowadziła; z powodzeniem 5 transmutacji epickich klejnotów. Dozwolone transmutacje to: ametryn, Oko Zula, kamień grozy, królewski bursztyn i majestatyczny cyrkon.', '', 'Wróć do Linzy Czarnośrub przy Żelaznej Tamie w Lodowej Koronie.', 'Transmutacje epickich klejnotów', '', '', '', 0),
(14160, 'plPL', 'Pismo pochwalne', 'Ten piękny pergamin wymienia wiele osiągnięć w dziedzinie jubilerstwa, których $gdokonał:dokonała; $N.$b$bZanieś to pismo Timothy\'emu Jonesowi w Dalaranie, a otrzymasz należytą nagrodę.', 'Dostarcz pismo pochwalne Timothy\'emu Jonesowi w Dalaranie.', '', 'Wróć do Timothy\'ego Jonesa w sklepie „Cartier i S-ka – Wykwintna Biżuteria” w Dalaranie.', '', '', '', '', 0),
(14166, 'plPL', 'Wdzięczni umarli', 'Dobrze znów odwiedzić przyjaciół i rodzinę, choć chyba trochę przesadziłam... Zjadłam już wszystko, co dla mnie przygotowali!$B$BCzy mogę cię prosić o jeszcze trochę tego pysznego chleba umarłych? Będę bardzo wdzięczna...$B$BPrzepis sprzedaje chyba tamten Chapman.', 'Zdobądź chleb umarłych i daj go radosnemu duchowi z Dalaranu na cmentarzu w Dalaranie.$B$BUżyj pomarańczowej aksamitki, aby zobaczyć niewidzialnego na co dzień ducha.', '', 'Wróć do radosnego ducha z Dalaranu nad Strumykiem Zmierzchu w Lesie Kryształowej Pieśni.', '', '', '', '', 0),
(14203, 'plPL', 'Nasiąknięty przepis', 'Wygląda to na resztki przepisu na mocne wino. Może właściciel „Jeszcze Jednego Kieliszka” w Dalaranie byłby nim zainteresowany...', 'Zanieś nasiąknięty przepis Christi Stockton w Mieście Dalaran.', '', 'Wróć do Christi Stockton przy Żelaznej Tamie w Lodowej Koronie.', '', '', '', '', 0),
(14457, 'plPL', 'Plan Słońcobójców', 'Jeden z moich informatorów w Podbrzuszu dostrzegł agenta Słońcobójców, który kupował odczynniki od handlarza w okolicy Czarnego Rynku. Słońcobójcy zwykle nie interesują się tym, co dzieje się w kanałach, więc to wyraźny znak, że coś knują.$B$BIdź do Podbrzusza, znajdź tego agenta Słońcobójców i rozpraw się z nim. Przeszukaj ciało – może znajdziesz coś, co naprowadzi nas na trop księgi ze Żmijowego Spoczynku. Nie możemy pozwolić, żeby to oni pierwsi dostarczyli ją do Lodowej Korony.', 'Zdobądź rozkazy Słońcobójców.', '', 'Wróć do arkanisty Tybalina w Srebrnej Enklawie w Dalaranie.', '', '', '', '', 0),
(24431, 'plPL', 'Nasiąknięty przepis', 'Wygląda to na resztki przepisu na mocne wino. Może właściciel „Jeszcze Jednego Kieliszka” w Dalaranie byłby nim zainteresowany...', 'Zanieś nasiąknięty przepis Christi Stockton w Mieście Dalaran.', '', 'Wróć do Christi Stockton w sklepie „Jeszcze Jeden Kieliszek” w Dalaranie.', '', '', '', '', 0),
(24506, 'plPL', 'W głębi Mroźnej Cytadeli', '$N! Podejdź szybko, muszę zamienić z tobą słowo!$B$BMoja królowa, Lady Sylwana Bieżywiatr, odkryła lukę w obronie Cytadeli Lodowej Korony, prowadzącą do miejsca, które nazwała „Kuźnią Dusz”. Zanim wyruszyła, przekazała mi, żebym znalazła zażartych wojowników i posłała ich do niej. Myślę, że się nadasz.$B$BUdaj się do niej, do wejścia do kuźni, $N.', 'Wejdź do Kuźni Dusz z boku Cytadeli Lodowej Korony i odnajdź Lady Sylwanę Bieżywiatr.', '', '', '', '', '', '', 0),
(24510, 'plPL', 'W głębi Mroźnej Cytadeli', '$N! Podejdź szybko, muszę zamienić z tobą słowo!$B$BMoja patronka, Lady Jaina Proudmoore, odkryła lukę w obronie Cytadeli Lodowej Korony, prowadzącą do miejsca, które nazwała „Kuźnią Dusz”. Zanim wyruszyła, przekazała mi, żebym znalazła jakąkolwiek pomoc... i, cóż, miałam nadzieję, że to będziesz ty.$B$BProszę, odszukaj ją tam jak najszybciej.', 'Wejdź do Kuźni Dusz z boku Cytadeli Lodowej Korony i odnajdź Lady Jainę Proudmoore.', '', '', '', '', '', '', 0),
(24557, 'plPL', 'Intryga Srebrnego Sojuszu', 'Jeden z moich informatorów w Podbrzuszu dostrzegł agenta Srebrnego Sojuszu, który zbierał informacje w karczmie „Sztuczki i Wrony”. Członków Srebrnego Sojuszu raczej nie spotyka się w kanałach, więc na pewno coś knują.$B$BIdź do Podbrzusza, znajdź tego agenta Srebrnego Sojuszu i zlikwiduj go. Przeszukaj ciało – może znajdziesz coś, co naprowadzi nas na trop księgi ze Żmijowego Spoczynku. Nie możemy pozwolić, żeby te przymilne mięczaki ze Srebrnego Sojuszu dostarczyły ją do Lodowej Korony przed nami.', 'Przechwyć rozkazy Srebrnego Sojuszu.', '', 'Wróć do magistra Hathorela w „Brudnym Zwierzęciu” w Dalaranie.', '', '', '', '', 0),
(24579, 'plPL', 'Sartharion musi zginąć!', 'Sartharion, Onyksowy Strażnik, strzeże jaj Stada Zmierzchu. Przebywa w Obsydianowym Sanktuarium w Komnacie Aspektów pod Świątynią Żmijowego Spoczynku.$B$BRada Sześciorga orzekła: Sartharion musi zginąć!', 'Zabij Sarthariona.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24580, 'plPL', 'Anub\'Rekhan musi zginąć!', 'Anub\'Rekhan, niegdyś potężny Pajęczy Władca nerubiańskiego imperium, został pochwycony przez Króla Lisza i spaczony w nieumarłą postać.$B$BTeraz, jako lord krypt, przesiaduje w swoim salonie w Pajęczej Dzielnicy w Naxxramas i snuje strategie dla Kel\'Thuzada.$B$BRada Sześciorga orzekła: Anub\'Rekhan musi zginąć!', 'Zabij Anub\'Rekhana.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24581, 'plPL', 'Nicz Siewca Zarazy musi zginąć!', 'Nicz Siewca Zarazy, zdrajca i tchórz! Tylko sam Król Lisz zamienił w sługi Plagi więcej dusz niż on!$B$BRuszaj co prędzej do Naxxramas. Znajdziesz go w Dzielnicy Zarazy, gdzie kryje się za swoimi nieumarłymi sługami.$B$BZniszcz go! Rada Sześciorga orzekła: Nicz musi zginąć!', 'Zabij Nicza Siewcę Zarazy.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24582, 'plPL', 'Instruktor Razuwiusz musi zginąć!', 'Instruktor Razuwiusz przechadza się z wyższością po Dzielnicy Wojskowej Naxxramas. Mówi się, że tylko rycerz śmierci wyszkolony przez niego osobiście mógłby w ogóle sprostać mistrzostwu jego ostrza.$B$BTy i twoja drużyna udowodnicie, że wszyscy się mylą.$B$BRada Sześciorga orzekła: Razuwiusz musi zginąć!', 'Zabij instruktora Razuwiusza.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24583, 'plPL', 'Łacior musi zginąć!', 'Łacior, tak zwany „awatar wojny”, to plugastwo doskonałe. Zbiera też ciężkie żniwo wśród naszych sił na Smoczych Pustkowiach.$B$BZbierz towarzyszy i wejdź do Rewiru Konstruktów w Naxxramas. Rozłóż ten konstrukt na części.$B$BRada Sześciorga orzekła: Łacior musi zginąć!', 'Zabij Łaciora.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24584, 'plPL', 'Malygos musi zginąć!', 'Nasze zasoby są na wyczerpaniu. Malygos, Tkacz Zaklęć, wysysa ze świata całą magię i gromadzi ją w Oku Wieczności. Bez magii jesteśmy zgubieni.$B$B$N, wojnę o Nexus trzeba zakończyć. Rada Sześciorga orzekła: Malygos musi zginąć!', 'Zabij Malygosa.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24585, 'plPL', 'Płomienny Lewiatan musi zginąć!', 'Na Terenach Formacji czeka pierwsza linia obrony Ulduaru: Płomienny Lewiatan.$B$BKirin Tor otrzymał informacje, z których wynika, że ta maszyna stworzona przez Opiekunów wkrótce zostanie przewieziona w nieujawnione miejsce i spuszczona ze smyczy, by siać spustoszenie wśród śmiertelników Azeroth.$B$BDo tego nie może dojść. Rada Sześciorga orzekła: Płomienny Lewiatan musi zginąć!', 'Zabij Płomiennego Lewiatana.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24586, 'plPL', 'Żyletołuskacz musi zginąć!', 'Żyletołuskacz zwykle nie opuszcza swojego gniazda w pobliżu Kolosalnej Kuźni w Ulduarze. Ostatnio jednak widziano, jak zsyła deszcz ognia na ziemie poza kompleksem tytanów.$B$BChoć historia tej matki miotu jest smutna, stanowi ona bezpośrednie zagrożenie dla całej Północnej Grani. Rada Sześciorga orzekła: Żyletołuskacz musi zginąć!', 'Zabij Żyletołuskacza.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24587, 'plPL', 'Ignis musi zginąć!', 'Wielki olbrzym ognia Ignis, mistrz pieca, trudzi się w Kolosalnej Kuźni Ulduaru. Na rozkaz Lokena Ignis tworzy broń o przerażającej mocy.$B$BRada Sześciorga orzekła: Ignis musi zginąć!', 'Zabij Ignisa.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24588, 'plPL', 'Dekonstruktor XT-002 musi zginąć!', 'Dekonstruktor XT-002, kolejny dziwaczny konstrukt Mimirona, naprawdę uważa się za syna Opiekuna. Nie daj się zwieść jego udawanej niewinności. To śmiercionośna maszyna!$B$BDekonstruktora znajdziesz na Złomowisku Ulduaru. Rada Sześciorga orzekła: Dekonstruktor XT-002 musi zginąć!', 'Zabij Dekonstruktora XT-002.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24589, 'plPL', 'Lord Jaraxxus musi zginąć!', 'Arcymag Timear przewidział straszliwe wydarzenie, które zaraz nastąpi. Pewien głupi gnomi czarnoksiężnik przypadkiem przyzwie eredarskiego lorda Płonącego Legionu w sam środek Próby Krzyżowca.$B$BMusisz tam być, gdy to się stanie, $N. Jeśli lord Jaraxxus ucieknie, otworzy portal i Płonący Legion znów wleje się do naszego świata.$B$BRada Sześciorga orzekła: Lord Jaraxxus musi zginąć!', 'Zabij lorda Jaraxxusa.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24590, 'plPL', 'Lord Kościejec musi zginąć!', 'Lord Kościejec strzeże Mroźnego Tronu w Komnacie Iglicy. Złożony przez Króla Lisza z kości tysiąca pokonanych poszukiwaczy przygód, Kościejec włada mocą samego tronu.$B$BBez zniszczenia tej kościanej zjawy nie ma nadziei na zdobycie Cytadeli Lodowej Korony.$B$BRada Sześciorga orzekła: Lord Kościejec musi zginąć!', 'Zabij lorda Kościejca.$B$BTo zadanie można ukończyć w rajdzie dowolnej wielkości i na dowolnym poziomie trudności.', '', 'Wróć do arcymaga Lan\'dalocka w Dalaranie.', '', '', '', '', 0),
(24803, 'plPL', 'Kalu\'acki turniej wędkarski', '', '', '', 'Wróć do starszego Czystej Wody w Dolinie Cierniodławów.', '', '', '', '', 0),
(24806, 'plPL', 'Więcej szczęścia następnym razem', '', '', '', 'Wróć do starszego Czystej Wody w Dolinie Cierniodławów.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(12790, 'plPL', 'Doskonale, $N. Teraz już wiesz, jak zejść do Lasu Kryształowej Pieśni i jak stamtąd wrócić.', 0),
(12958, 'plPL', 'Oto twój Dalarański żeton jubilerski, tak jak obiecałem. Wróć jutro – na pewno będę potrzebował od ciebie kolejnej rzeczy!', 0),
(12959, 'plPL', 'Oto twój Dalarański żeton jubilerski, tak jak obiecałem. Wróć jutro – na pewno będę potrzebował od ciebie kolejnej rzeczy!', 0),
(12960, 'plPL', 'Oto twój Dalarański żeton jubilerski, tak jak obiecałem. Wróć jutro – na pewno będę potrzebował od ciebie kolejnej rzeczy!', 0),
(12961, 'plPL', 'Oto twój Dalarański żeton jubilerski, tak jak obiecałem. Wróć jutro – na pewno będę potrzebował od ciebie kolejnej rzeczy!', 0),
(12962, 'plPL', 'Oto twój Dalarański żeton jubilerski, tak jak obiecałem. Wróć jutro – na pewno będę potrzebował od ciebie kolejnej rzeczy!', 0),
(12963, 'plPL', 'Oto twój Dalarański żeton jubilerski, tak jak obiecałem. Wróć jutro – na pewno będę potrzebował od ciebie kolejnej rzeczy!', 0),
(13041, 'plPL', 'Oto twój Dalarański żeton jubilerski, tak jak obiecałem. Nowe dostawy wysyłam bez przerwy, więc zaglądaj do mnie co jakiś czas i sprawdzaj, czego potrzebuję.', 0),
(13100, 'plPL', 'Wygląda świetnie! Dzięki!', 0),
(13101, 'plPL', 'Tego jedzenia starczy dla wszystkich! Klienci na pewno będą zadowoleni.', 0),
(13102, 'plPL', 'Zniknie w mgnieniu oka! Dzięki!', 0),
(13103, 'plPL', 'Aha, to chyba wyborny rocznik!', 0),
(13107, 'plPL', 'Doskonale! Mam tylko nadzieję, że Dalarańscy Niszczyciele wreszcie coś wygrają!', 0),
(13112, 'plPL', 'To jedzenie od Awila? Możesz mi przyrzec, że nie ma w nim gnoma?', 0),
(13113, 'plPL', 'To powinno zadowolić moich gości. Tylko nie mów im, że to od Awila.', 0),
(13114, 'plPL', 'Gulasz wygląda dobrze. Dzięki za pomoc.', 0),
(13115, 'plPL', 'To wino jest zdumiewające! Muszę wiedzieć, skąd pochodzi.', 0),
(13116, 'plPL', 'Doskonale! Mam tylko nadzieję, że Dalarańscy Niszczyciele wreszcie coś wygrają!', 0),
(13148, 'plPL', 'Gdzie to $gznalazłeś:znalazłaś;?! Wiele takich naszyjników skradziono z jednej z moich dostaw kilka tygodni temu! Pozwól, że odwdzięczę się tym żetonem jubilerskim.', 0),
(13158, 'plPL', 'W ostatniej chwili.$b$bCzy jesteś $ggotów:gotowa; bronić Dalaranu, $N?', 0),
(13159, 'plPL', 'A więc kryzys zażegnany?$b$bTo naprawdę dobre wieści. Przekażę je Rhoninowi.$b$bProszę, przyjmij to wraz z wdzięcznością Dalaranu.', 0),
(13571, 'plPL', 'Ponad stęchłym odorem niemytego ciała wyczuwasz znajomą woń! Wygląda na to, że ten niegdyś potężny poszukiwacz przygód darzy kungalusz prawdziwą miłością.$b$bZerkając przez kraty, z trudem odczytujesz przepis wypisany na jego ramieniu...', 0),
(13631, 'plPL', 'Jesteś. Miejmy nadzieję, że to zadziała. Dla dobra nas wszystkich.', 0),
(13819, 'plPL', 'Jesteś. Miejmy nadzieję, że to zadziała. Dla dobra nas wszystkich.', 0),
(13830, 'plPL', 'A więc zjedzenie jej czyni niewidzialnym... cóż za dziwny mechanizm obronny wykształciła ta sprytna ryba.$b$bMuszę to sobie na spokojnie przetrawić. To nie miał być kalambur, $N. Naprawdę. Może zajrzysz do mnie jutro?', 0),
(13832, 'plPL', 'No proszę, to może być coś cennego. Trudno powiedzieć, dopóki się tego nie oczyści i nie wyceni, ale nadal chętnie się wymienię, jeśli ty też chcesz.', 0),
(13833, 'plPL', 'Odważna z ciebie dusza, $N. Mam nadzieję, że nie $gstraciłeś:straciłaś; żadnej kończyny, przygotowując łowisko. Jeśli wędkarski bakcyl wciąż cię trzyma, wróć jutro, to jeszcze pogadamy.', 0),
(13834, 'plPL', 'No, no, no! $GZłowiłeś:Złowiłaś; strachoryby. Wiesz, przypomina mi to czasy, kiedy...$b$b<Marcia raczy cię opowieściami o przygodach i wędkowaniu tak długo, jak masz ochotę słuchać.>', 0),
(13836, 'plPL', 'Och, witaj, $N. Marcia mówiła, że przyniesiesz brakujące ramię tego biedaka.$b$bDała mi też tę sakwę, żebym ci ją przekazała jako nagrodę. Strasznie cuchnie, więc jeśli nie masz nic przeciwko, chętnie wymienię się od razu.', 0),
(13845, 'plPL', 'Trzeba odwagi, żeby nosić to przy sobie. Gdyby choć jedna kropla dotknęła twojej skóry, czekałaby cię śmierć w męczarniach.$b$bPozwól, że ci za nią zapłacę... Trucizna o wyjątkowej mocy zawsze mi się przyda.', 0),
(13959, 'plPL', 'Wygląda na to, że mały Roo świetnie się bawił w tym tygodniu. Wiem, że w sierocińcu doskwierała mu samotność i bardzo chciał poznać nowych przyjaciół. Ogromnie ci dziękuję, że $gzgodziłeś:zgodziłaś; się nim zaopiekować.', 0),
(13960, 'plPL', 'Dziękuję, że $gzgodziłeś:zgodziłaś; się zaopiekować Kekekiem w tym tygodniu. Wiem, że potrafi dać się we znaki, ale myślę, że gdy poświęci mu się więcej uwagi i zyska jeszcze kilku przyjaciół, będzie sobie radził o wiele lepiej. Bez wątpienia przez całe tygodnie będzie opowiadał o swoich przygodach z tobą.', 0),
(14151, 'plPL', 'Bardzo dobrze, $N.$B$BA teraz cała sztuka polega na tym, by idealnie ustawić fasety...', 0),
(14160, 'plPL', 'Piękna lista dokonań, $N! Należy ci się sowita nagroda za twoje osiągnięcia.', 0),
(14203, 'plPL', 'To niezłe znalezisko, <name>. Nie mogę pozwolić, żebyś $gsprzedał:sprzedała; to komuś innemu, więc jestem gotowa hojnie zapłacić.', 0),
(14457, 'plPL', '<Arkanista Tybalin przegląda zdobyte rozkazy.>$B$BAgent, którego $gprzechwyciłeś:przechwyciłaś;, miał przewieźć księgę ze Żmijowego Spoczynku do Lodowej Korony po spotkaniu z niejakim magistrem Hathorelem w Sanktuarium Słońcobójców. Musimy zdobyć tę księgę, $N, i to jest nasza szansa. Nie będzie jednak łatwo.', 0),
(24431, 'plPL', 'To niezłe znalezisko, $N. Nie mogę pozwolić, żebyś $gsprzedał:sprzedała; to komuś innemu, więc jestem gotowa hojnie zapłacić.', 0),
(24506, 'plPL', 'Dobrze. $N, słyszałam o tobie. Świetnie nadasz się do tych zadań.$B$BDostaliśmy rzadką szansę, by zapuścić się w głąb Cytadeli Lodowej Korony, ale musimy działać szybko, jeśli Arthas ma nas nie zauważyć.', 0),
(24510, 'plPL', '$N! Tak się cieszę, że $gprzybyłeś:przybyłaś;!$B$BDostaliśmy rzadką szansę, by zapuścić się w głąb Cytadeli Lodowej Korony, ale musimy działać szybko, jeśli Arthas ma nas nie zauważyć.', 0),
(24557, 'plPL', '<Magister Hathorel czyta zdobyte rozkazy.>$B$BAgent, którego $gprzechwyciłeś:przechwyciłaś;, miał dostarczyć księgę ze Żmijowego Spoczynku do Lodowej Korony po spotkaniu z niejakim arkanistą Tybalinem w Srebrnej Enklawie. Musimy odzyskać tę księgę, $N, a mamy tylko jedną szansę, zanim opuści miasto. Trzeba działać szybko.', 0),
(24580, 'plPL', 'Wieść o twoim sukcesie dotarła tu przed tobą. Anub\'Rekhana już nie ma. $GWyświadczyłeś:Wyświadczyłaś; mu wielką przysługę, $N.', 0),
(24581, 'plPL', 'Jeden cierń w naszym boku mniej. Po zniszczeniu Nicza badania Plagi nad udoskonalaniem sposobów tworzenia nieumarłych staną w miejscu.', 0),
(24582, 'plPL', 'Dobra robota, $N. Po śmierci Razuwiusza dowództwo wojskowe Plagi w Naxxramas pogrążyło się w chaosie.', 0),
(24583, 'plPL', 'Dobra robota, $N. Po śmierci Razuwiusza dowództwo wojskowe Plagi w Naxxramas pogrążyło się w chaosie.', 0),
(24584, 'plPL', 'Po pokonaniu Malygosa wojna o Nexus powinna szybko dobiec końca. Masz wdzięczność Kirin Toru, $N.', 0),
(24585, 'plPL', 'Nie przestaje mnie zdumiewać, jakie okropieństwa można stworzyć za pomocą techniki.', 0),
(24586, 'plPL', 'Teraz Veranus może wreszcie spoczywać w pokoju.', 0),
(24587, 'plPL', 'Ufam, że nie $gmusiałeś:musiałaś; mierzyć się ze zbyt wieloma jego pomocnikami – żelaznymi konstruktami?', 0),
(24588, 'plPL', 'Największą słabością Ulduaru jest ślepa wiara jego panów w to, że ich wynalazki go ochronią.', 0),
(24589, 'plPL', 'Całe Azeroth ma szczęście, że Timear przewidział przybycie eredarskiego lorda, a ty $gzdążyłeś:zdążyłaś; na czas, by go zgładzić.', 0),
(24590, 'plPL', 'Dzięki tobie Mroźny Tron stracił swojego głównego strażnika. Teraz nasze ataki na siły Króla Lisza będą jeszcze skuteczniejsze.', 0),
(24803, 'plPL', 'Nie stój tak! Daj mi rekina, a ogłoszę twoje zwycięstwo!', 0),
(24806, 'plPL', 'Cóż, miło, że w ogóle próbujesz. Nie chcę, żebyś $gmyślał:myślała;, że twój wysiłek poszedł na marne, więc mam coś dla ciebie.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(12790, 'plPL', 'Wyczuwam, że nie $gwypróbowałeś:wypróbowałaś; jeszcze obu kryształów teleportacyjnych.$B$BNic nie szkodzi, nie spiesz się.', 0),
(12958, 'plPL', 'Masz amulet z krwawego nefrytu do mojej dostawy do Undermine?', 0),
(12959, 'plPL', 'Masz jarzącą się figurkę z kości słoniowej do mojej dostawy do Undermine?', 0),
(12960, 'plPL', 'Masz broszkę nikczemnego słońca do mojej dostawy do Undermine?', 0),
(12961, 'plPL', 'Masz misterną figurkę z kości do mojej dostawy do Undermine?', 0),
(12962, 'plPL', 'Masz relikwię jasnej zbroi do mojej dostawy do Undermine?', 0),
(12963, 'plPL', 'Masz zmienne słoneczne cacko do mojej dostawy do Undermine?', 0),
(13041, 'plPL', 'Masz już ten chalcedon?', 0),
(13100, 'plPL', 'Masz dla mnie coś do jedzenia?$B$BNigdy nie mogę się wyrwać ze sklepu, choćby na minutę.', 0),
(13101, 'plPL', 'Gdzie moje jedzenie? Lada chwila zjawią się tu uczestnicy zjazdu!', 0),
(13102, 'plPL', 'Mam tu na dole głodnych ludzi! Potrzebujemy gulaszu.', 0),
(13103, 'plPL', '$GWidziałeś:Widziałaś; może służącego z moim półmiskiem wina i sera? Porządnie zgłodniałem!', 0),
(13107, 'plPL', 'Jestem prawie gotów do wyjścia, potrzebuję tylko jedzenia i żeby zjawili się moi kumple... eee... moi koledzy magowie.', 0),
(13112, 'plPL', 'Masz coś dla mnie? Tak rzadko udaje mi się wyrwać ze sklepu.', 0),
(13113, 'plPL', 'Gdzie moje jedzenie? Goście zaraz tu będą!', 0),
(13114, 'plPL', 'Tylko dopilnuj, żeby tym razem w gulaszu nie było gnoma!', 0),
(13115, 'plPL', '$GWidziałeś:Widziałaś; może służącego z moim półmiskiem wina i sera? Porządnie zgłodniałem!', 0),
(13116, 'plPL', 'Dopilnuj, żeby hot dogi z dziką gorczycą były w stu procentach z nosorożca i bez grama gnoma!', 0),
(13159, 'plPL', 'Już po wszystkim? $GZdołałeś:Zdołałaś; odeprzeć atak?', 0),
(13631, 'plPL', 'Jesteś $ggotów:gotowa;, $N?', 0),
(13819, 'plPL', 'Jesteś $ggotów:gotowa;, $N?', 0),
(13830, 'plPL', 'Widmoryba straszy przy każdej twojej próbie?$b$b<Marcia wygląda na wyjątkowo dumną ze swojego kalamburu.>', 0),
(13833, 'plPL', 'Jak idzie z krwawozębymi? Nie zapomnij, co ci mówiłam o robieniu krwawych plam.', 0),
(13834, 'plPL', 'Miej się na baczności, kiedy polujesz na strachoryby.', 0),
(13836, 'plPL', 'Cześć. Masz coś dla mnie?', 0),
(13845, 'plPL', 'Czy to jest to, o czym myślę, $N?', 0),
(13959, 'plPL', 'My musieć wracać? My chcieć zostać z tobą.', 0),
(13960, 'plPL', 'Kekek nie chcieć iść. Kekek chcieć zobaczyć więcej Północnej Grani z Jeursey.', 0),
(14151, 'plPL', '$GPrzeprowadziłeś:Przeprowadziłaś; transmutacje?', 0),
(14160, 'plPL', 'Dzień dobry, $n. Co tam masz?', 0),
(14203, 'plPL', 'Zawsze powtarzam: wino jest tylko tak szlachetne, jak ten, kto je pije.', 0),
(14457, 'plPL', '$GZnalazłeś:Znalazłaś; przy tym agencie coś przydatnego?', 0),
(24431, 'plPL', 'Zawsze powtarzam: wino jest tylko tak szlachetne, jak ten, kto je pije.', 0),
(24557, 'plPL', '$GZnalazłeś:Znalazłaś; przy tym agencie coś przydatnego?', 0),
(24803, 'plPL', 'My, Kalu\'ak, mamy długą tradycję doskonalenia wędkarskich umiejętności: co tydzień wystawiamy je na próbę.$B$BPierwsza osoba, która złowi żarłacza czarnopłetwego i mi go przyniesie, otrzyma sowitą nagrodę i zasłynie jako najlepszy wędkarz północy... przynajmniej na parę dni.$B$BUlubionym przysmakiem żarłacza czarnopłetwego jest karłowata podnawka. Spróbuj łowić żarłacza wszędzie tam, gdzie zwykle łowi się podnawki.', 0),
(24806, 'plPL', 'Niestety mamy już dziś zwycięzcę, $gmłody:młoda; $N. Jeśli jednak przyniesiesz rekina, dopilnuję, by wrócił do wody, a może znajdzie się też dla ciebie jakiś drobiazg...', 0);
