(37339, 'plPL', 'Formuła: zaklęcie broni – pogromca olbrzymów', 'Uczy trwałego zaklinania broni do walki wręcz, by czasem spowalniała ruch celu i zadawała dodatkowe obrażenia olbrzymom. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(37340, 'plPL', 'Formuła: zaklęcie torsu – wyjątkowa nieugiętość', 'Uczy trwałego zaklinania zbroi na tors, co zwiększa wskaźnik nieugiętości o 20. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(37344, 'plPL', 'Formuła: zaklęcie broni – lodołamacz', 'Uczy trwałego zaklinania broni do walki wręcz, by czasem zadawała obrażenia od ognia. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(37347, 'plPL', 'Formuła: zaklęcie płaszcza – tkanina tytanów', 'Uczy trwałego zaklinania płaszcza, co zwiększa wskaźnik obrony o 16. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(37349, 'plPL', 'Formuła: zaklęcie płaszcza – pancerz cienia', 'Uczy trwałego zaklinania płaszcza, co nieznacznie wzmacnia ukrycie i zwiększa zręczność o 10. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
