(44471, 'plPL', 'Formuła: zaklęcie płaszcza – mocarny pancerz', 'Uczy trwałego zaklinania płaszcza, co daje 225 pkt. dodatkowego pancerza. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44472, 'plPL', 'Formuła: zaklęcie płaszcza – większa szybkość', 'Uczy trwałego zaklinania płaszcza, co zwiększa wskaźnik szybkości o 23. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44473, 'plPL', 'Formuła: zaklęcie broni – zguba Plagi', 'Uczy trwałego zaklinania dwuręcznej broni do walki wręcz, co zwiększa siłę ataku przeciw nieumarłym o 140. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44481, 'plPL', 'Zabawkowy goryl Zgrzytotryba', 'Teraz z dżunglowymi skokami!', 0),
(44482, 'plPL', 'Niezawodna miedziana wyścigówka', 'Czujesz żądzę prędkości?', 0),
(44483, 'plPL', 'Formuła: zaklęcie broni dwuręcznej – masakra', 'Uczy trwałego zaklinania dwuręcznej broni do walki wręcz, co zwiększa siłę ataku o 110. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44484, 'plPL', 'Formuła: zaklęcie karwaszy – większy szturm', 'Uczy trwałego zaklinania karwaszy, co zwiększa siłę ataku o 50. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44485, 'plPL', 'Formuła: zaklęcie rękawic – zbrojny', 'Uczy trwałego zaklinania rękawic, co zwiększa generowane zagrożenie o 2% i wskaźnik parowania o 10. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44486, 'plPL', 'Formuła: zaklęcie broni – znakomita potęga', 'Uczy trwałego zaklinania broni do walki wręcz, co zwiększa siłę ataku o 65. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44487, 'plPL', 'Formuła: zaklęcie broni – mocarna moc czarów', 'Uczy trwałego zaklinania broni do walki wręcz, co zwiększa moc czarów o 63. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44488, 'plPL', 'Formuła: zaklęcie płaszcza – mądrość', 'Uczy trwałego zaklinania płaszcza, co nieznacznie zmniejsza zagrożenie i zwiększa ducha o 10. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44489, 'plPL', 'Formuła: zaklęcie torsu – potężne statystyki', 'Uczy trwałego zaklinania zbroi na tors, co zwiększa wszystkie statystyki o 10. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44490, 'plPL', 'Formuła: zaklęcie butów – większy szturm', 'Uczy trwałego zaklinania butów, co zwiększa siłę ataku o 32. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44491, 'plPL', 'Formuła: zaklęcie butów – żywotność kiełzarów', 'Uczy trwałego zaklinania butów, co nieznacznie zwiększa szybkość poruszania się i zwiększa wytrzymałość o 15. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44492, 'plPL', 'Formuła: zaklęcie broni – szał berserkera', 'Uczy trwałego zaklinania broni do walki wręcz, by czasem zwiększała twoją siłę ataku kosztem zmniejszenia pancerza. Wymaga przedmiotu co najmniej 60. poziomu.', 0),
(44494, 'plPL', 'Formuła: zaklęcie broni – osłona życia', 'Uczy trwałego zaklinania broni do walki wręcz, by czasem leczyła władającego nią przy trafieniu w walce wręcz. Wymaga przedmiotu co najmniej 60. poziomu.', 0);
