INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(3542, 'plPL', 'Arcymag Antonidas, Wielki Mag Kirin Toru$B$BWielkie miasto Dalaran znów stoi – jako świadectwo wytrwałości i woli swego najwspanialszego syna.$B$BTwoje poświęcenie nie poszło na marne, najdroższy przyjacielu.$B$B$BZ miłością i czcią,$B$BJaina Proudmoore', 0),
(3543, 'plPL', 'Od wielu, wielu lat to magiczne więzienie trzyma mnie pod kluczem. Tej nocy ucieknę. Mam wszystko, czego potrzebuję do ucieczki.$B$B<Ten fragment listu jest nieczytelny – atrament rozmyła woda>$B$BDlaczego jestem tu tak długo? Czemu mnie to spotkało? Dzień po dniu te myśli krążą mi po głowie. Co trzeba zrobić, żeby na to zasłużyć?$B$B<Ten fragment listu jest nieczytelny – atrament rozmyła woda>$B$BMoże dowiem się w następnym życiu.', 0),
(3562, 'plPL', 'Maleńka gnomka wyjrzała przez balustradę na zaciszny dalarański dziedziniec.$B$B„Widok z balkonu jest niesamowity. Musisz to zobaczyć!”$B$BPłytowe nogawice zaskrzypiały, gdy Marcus podszedł bliżej; wziął głęboki oddech i w zamyśleniu podrapał się po zarośniętym podbródku.$B$B„Przybytek Bohaterów to nie byle co. A w pokoju jest coś, co może cię zainteresować”.$B$BTavi wpadła w podskokach do pokoju i zawahała się tylko na chwilę, nim wskoczyła na ogromne łoże. Odwróciła się i spojrzała na Marcusa wielkimi jak spodki oczami, po czym zmrużyła je figlarnie, a jej promienny uśmiech ustąpił miejsca diabolicznemu grymasowi.', 0),
(3563, 'plPL', '„Masz ochotę na dodatkowe towarzystwo?” – zamruczała, a jej dłonie kreśliły zawiłe gesty rytuału przywołania; przerwała dopiero wtedy, gdy poczuła za plecami ciepło nowej istoty.$B$BZ twarzy Marcusa odpłynęła cała krew. Z trudem wydusił z siebie protest: „Ja... ja nie sądzę, żeby to wypadało”.$B$BZdezorientowana Tavi odwróciła się, by zobaczyć, co jest nie tak. Stał tam w gotowości ohydny ogar spaczenia; ślinił się na podłogę i wpatrywał uporczywie w na wpół rozebranego ze zbroi paladyna.$B$B„Nie! Nie, nie to miałam na myśli” – wyjąkała, odsyłając głodnego demona. „Przepraszam, to nie do końca moja specjalizacja...”', 0),
(3564, 'plPL', 'Marcus ujął obie jej dłonie w jedną swoją i uspokoił ją: „Nic się nie stało. A jaka jest twoja specjalizacja?”$B$BPoderwała głowę, a jej oczy zapłonęły nowym życiem, gdy mroczna energia popłynęła przez jej dłonie w Marcusa i rzuciła go w męczarniach na kolana.$B$B„Prawdę mówiąc, udręka”.$B', 0),
(3565, 'plPL', 'Zaciskając zęby, Marcus wykonał gest, a rozbłysk światła, który go ogarnął, przywrócił mu siły.$B$BTavi patrzyła z niepokojem, jak prostuje się na całą wysokość i okrywa ją swoim cieniem. Wyrzucił dłoń przed siebie i posłał przez nią falę prawej mocy. Oczy uciekły jej w głąb czaszki; chwiała się przez kilka sekund, nim odzyskała przytomność.$B$B„Ostatnio obrałem ścieżkę... odwetu”.$B$BNa jej twarz powrócił psotny uśmieszek: „No to będzie zabawa”.$B$B<Aby przeczytać pozostałe strony, wymagany jest poziom 99.>', 0),
(3597, 'plPL', 'Masz się spotkać z arkanistą Tybalinem na najwyższym piętrze Srebrnej Enklawy. Powierzy ci księgę, która nie ma ceny. Poruszaj się dyskretnie i strzeż tej księgi jak oka w głowie. Zanieś ją jak najszybciej Caladisowi Jasnowłóczni przy Spoczynku Quel\'Delara.', 0),
(3598, 'plPL', 'Masz się spotkać z magistrem Hathorelem w „Brudnym Zwierzęciu”. Powierzy ci księgę, która nie ma ceny. Poruszaj się dyskretnie i strzeż tej księgi jak oka w głowie. Dostarcz ją jak najszybciej Myralionowi Słonecznemu Żarowi przy Spoczynku Quel\'Delara.', 0);
