(271, 'plPL', 'Dalaran, bank w kanałach', 0),
(272, 'plPL', 'Dalaran, karczma w kanałach', 0),
(273, 'plPL', 'Dalaran, tunel kanałów', 0),
(274, 'plPL', 'Dalaran, sprzedawcy w kanałach', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(29506, 0, 0, 'plPL', 'Witaj, wędrowcze!'),
(31134, 4, 0, 'plPL', 'Czyżbym przeszkadzała?'),
(31134, 5, 0, 'plPL', 'Drżyjcie i gińcie!'),
(31134, 6, 0, 'plPL', 'Świat zapomniał, czym jest prawdziwa magia! Niech to będzie dla niego przestrogą!'),
(32170, 0, 0, 'plPL', 'Bitwa o panowanie nad Zimościskiem rozpocznie się za 5 minut! Przygotujcie się do walki!'),
(32706, 0, 0, 'plPL', 'Anar\'alah belore, $N!'),
(32711, 0, 0, 'plPL', 'Jak tu spokojnie...'),
(32714, 0, 0, 'plPL', 'Niech Elune ci błogosławi, $gczempionie:czempionko;.'),
(32718, 0, 0, 'plPL', 'Bywaj w zdrowiu, $gczempionie:czempionko;.'),
(32719, 0, 0, 'plPL', 'Jak leci, mon!'),
(32720, 0, 0, 'plPL', 'Dobrze cię widzieć, $gczempionie:czempionko;.'),
(32838, 0, 0, 'plPL', 'Nie cierpisz, kiedy w konia robi cię GNOM?!'),
(33293, 7, 0, 'plPL', 'Czas na nową zabawę! Moje stare zabawki będą walczyć z nowymi zabawkami!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(3287, 'plPL', 'Dobra robota!', '', 0),
(4428, 'plPL', '%s wpada w szał berserkera!', '%s wpada w szał berserkera!', 0),
(13000, 'plPL', 'Tylko odrobinę skosztuję...', '', 0),
(13002, 'plPL', 'Nie ma stąd wyjścia.', '', 0),
(13003, 'plPL', 'Tak, uciekajcie! Wtedy krew szybciej krąży!', '', 0),
(13004, 'plPL', 'Ach... zapraszam do mojego saloniku.', '', 0),
(13005, 'plPL', 'Ćśś... wkrótce będzie po wszystkim.', '', 0),
(13006, 'plPL', 'Słyszę bicie małych serduszek. Tak... biją coraz szybciej... wkrótce przestaną bić.', '', 0),
(13007, 'plPL', 'Dokąd iść? Co robić? Tyle wyborów, a każdy kończy się bólem, kończy się śmiercią.', '', 0),
(13008, 'plPL', 'Którego zjeść najpierw? Tak trudno wybrać. Wszyscy pachną tak smakowicie...', '', 0),
(13009, 'plPL', 'Podejdźcie bliżej. Smakowite kąski. Zbyt długo nie jadłem, zbyt długo nie piłem krwi.', '', 0),
(13061, 'plPL', 'Chwała panu!', '', 0),
(13063, 'plPL', 'Giń, intruzie!', '', 0),
(13064, 'plPL', 'Będę służył panu... po śmierci!', '', 0),
(13067, 'plPL', 'Powstańcie, moi żołnierze! Powstańcie i walczcie raz jeszcze!', '', 0),
(13068, 'plPL', 'Łacior chcieć się bawić!', '', 0),
(13069, 'plPL', 'Kel\'Thuzad zrobić z Łaciora swój awatar wojny!', '', 0),
(13070, 'plPL', 'Co... się sta...', '', 0),
(13072, 'plPL', 'Dopiero się rozgrzewam!', '', 0),
(13073, 'plPL', 'Stańcie i walczcie!', '', 0),
(13074, 'plPL', 'Pokażcie, na co was stać!', '', 0),
(13075, 'plPL', 'Róbcie, czego was nauczyłem!', '', 0),
(13076, 'plPL', 'Żadnej litości!', '', 0),
(13077, 'plPL', 'Rozczarowujecie mnie, uczniowie!', '', 0),
(13078, 'plPL', 'Koniec ćwiczeń! Pokażcie, czego się nauczyliście!', '', 0),
(13079, 'plPL', 'Honorowa... śmierć.', '', 0),
(13080, 'plPL', 'Podetnij mu nogę... Masz z tym jakiś problem?', '', 0),
(13081, 'plPL', 'Trzeba było zostać w domu.', '', 0),
(13082, 'plPL', '%s wydaje triumfalny okrzyk.', '', 0),
(13136, 'plPL', 'Weźcie się do roboty, zanim zamiast kukły treningowej postawię was i urządzę sobie własną rozgrzewkę!', '', 0),
(13443, 'plPL', 'Anub\'Rekhan zaczyna wypuszczać rój owadów!', '', 0),
(21736, 'plPL', 'Dobra robota!', '', 0),
(28673, 'plPL', 'Witaj. Czy mogę ci zaproponować odpoczynek albo posiłek?', 'Witaj. Czy mogę ci zaproponować odpoczynek albo posiłek?', 0),
(28804, 'plPL', 'Witaj w biurze rejestracji gildii Dalaranu. W czym mogę pomóc?', 'Witaj w biurze rejestracji gildii Dalaranu. W czym mogę pomóc?', 0),
(29070, 'plPL', 'Moje zadanie wykonane!', '', 0),
(29482, 'plPL', '', 'Witaj w mojej kuchni! Przyrządzamy tu jedne z najlepszych potraw w Dalaranie.', 0),
(29483, 'plPL', 'Chcę się uczyć gotowania.', 'Chcę się uczyć gotowania.', 0),
(29730, 'plPL', 'Twoje życie przepadło!', '', 0),
(30326, 'plPL', 'Stoisz przed mistrzem magii tajemnej. Niemądrze byłoby rzucać mi wyzwanie. Za sobą zostawiłem wiele płonących ciał.', '', 0),
(30327, 'plPL', '', 'Moje życie i duszę wypełniają wspomnienia o nieznośnej Hordzie. Przeżyłam czasy smutku, rozpaczy i poświęceń. Bitewny gniew nigdy nie opuści mojego serca!', 0),
(30330, 'plPL', 'To portal na pole bitwy w Kotlinie Aratorskiej.', '', 0),
(30331, 'plPL', 'To portal na pole bitwy w Dolinie Alterak.', '', 0),
(30332, 'plPL', 'To portal na pole bitwy Oko Cyklonu.', '', 0),
(30333, 'plPL', 'Nie jesteś jeszcze dość $gsilny:silna;, by walczyć w Oku Cyklonu. Wróć, gdy zdobędziesz więcej doświadczenia.', 'Nie jesteś jeszcze dość $gsilny:silna;, by walczyć w Oku Cyklonu. Wróć, gdy zdobędziesz więcej doświadczenia.', 0),
(30334, 'plPL', 'To portal na pole bitwy w Wąwozie Wojennej Pieśni.', '', 0),
(30345, 'plPL', 'Co tam słychać?$B$BTy tu jeść przyjść, mon? A może uczyć się gotowania od najlepszych, co?', '', 0),
(30372, 'plPL', '', 'Witaj! Może kupisz trochę sprzętu wędkarskiego albo weźmiesz lekcję czy dwie?', 0),
(30897, 'plPL', 'Kiedyś miałem wszystko. Sławę, majątek, pełen komplet najlepszego ekwipunku gladiatora... a potem wszystko to przepuściłem.$B$BGdy Kartel przyłapał mnie na ustawianiu walk... handlowaniu zwycięstwami... było po mnie.$B$BTeraz mam tylko te łachmany i zniszczoną wątrobę.', '', 0),
(31313, 'plPL', 'Nie jesteś jeszcze dość $gsilny:silna;, by walczyć na Wybrzeżu Pradawnych. Wróć, gdy zdobędziesz więcej doświadczenia.', 'Nie jesteś jeszcze dość $gsilny:silna;, by walczyć na Wybrzeżu Pradawnych. Wróć, gdy zdobędziesz więcej doświadczenia.', 0),
(31315, 'plPL', 'Nie możemy pozwolić, by Horda obróciła przeciwko nam ukryte tajemnice Wybrzeża Pradawnych. Dołączysz tam do naszych dzielnych żołnierzy?', 'Nie możemy pozwolić, by Horda obróciła przeciwko nam ukryte tajemnice Wybrzeża Pradawnych. Dołączysz tam do naszych dzielnych żołnierzy?', 0),
(31318, 'plPL', 'Shadronie! Do mnie! Wszystko jest zagrożone!', '', 0),
(31319, 'plPL', 'Tenebronie! Ty także masz strzec jaj!', '', 0),
(31320, 'plPL', 'Vesperonie, lęg jest w niebezpieczeństwie! Pomóż mi!', '', 0),
(31321, 'plPL', '%s wbija w ciebie wzrok!', '%s wbija w ciebie wzrok!', 0),
(31341, 'plPL', 'Oto cena... porażki...', '', 0),
(31362, 'plPL', '%s wzburza otaczającą go lawę!', '', 0),
(31363, 'plPL', 'Jakie łatwopalne robaczki...', '', 0),
(31368, 'plPL', 'To żałosne oblężenie kończy się TERAZ!', '', 0),
(31400, 'plPL', 'Moim zadaniem jest strzec tych jaj. Prędzej ujrzę was w płomieniach, niż pozwolę, by stała się im krzywda!', '', 0),
(31472, 'plPL', 'Już nie zaczerpniesz tchu!', '', 0),
(31718, 'plPL', '', 'Dzielna obrona, ale to miasto musi zostać zrównane z ziemią. Sama spełnię wolę Malygosa!', 0),
(31723, 'plPL', '', 'Skończmy z tym teraz, czempioni Kirin Toru!', 0),
(31725, 'plPL', '', 'Zniszczę Kirin Tor!', 0),
(31726, 'plPL', '', 'Dalaran UPADNIE!', 0),
(31727, 'plPL', '', 'Tak kończy się wasz opór wobec Tkacza Zaklęć.', 0),
(31728, 'plPL', '', 'Może... nie doceniliśmy... was.', 0),
(31740, 'plPL', '', 'Kto z was zdoła się oprzeć mojej mocy?', 0),
(31759, 'plPL', 'Pośledniejsze istoty wdzierają się tutaj! Szkoda, że wasza nadmierna odwaga nie równoważy waszej głupoty!', '', 0),
(31760, 'plPL', 'Nikt poza Błękitnym Stadem nie jest tu mile widziany. Może to sprawka Alexstrazy? Cóż, w takim razie posłała was na śmierć!', '', 0),
(31761, 'plPL', 'Co niby chcecie osiągnąć? Wedrzeć się bezczelnie do mojej domeny... użyć magii... przeciwko MNIE?', '', 0),
(31762, 'plPL', 'Tutaj nic mnie nie ogranicza. Zasady waszej ukochanej rzeczywistości tu nie obowiązują. W tej krainie to ja rządzę!', '', 0),
(31763, 'plPL', 'Daję wam jedną szansę. Przysięgnijcie mi wierność, a może nie wyrżnę was za waszą zuchwałość.', '', 0),
(31764, 'plPL', 'Moja cierpliwość się wyczerpała. Pozbędę się was!', '', 0),
(31765, 'plPL', 'Niewielu zaznało bólu, jaki wam teraz zadam!', '', 0),
(31767, 'plPL', 'Wasza głupota w końcu was dopadła!', '', 0),
(31768, 'plPL', 'Kolejne artefakty do skonfiskowania.', '', 0),
(31769, 'plPL', 'Jakież to naiwne.', '', 0),
(31772, 'plPL', 'Miałem nadzieję szybko zakończyć wasz żywot, ale okazaliście się bardziej... odporni, niż się spodziewałem. Mimo to wasze wysiłki są daremne. To wy, lekkomyślni, nieostrożni śmiertelnicy, ponosicie winę za tę wojnę. Robię, co muszę, a jeśli oznacza to waszą zagładę... to NIECH TAK BĘDZIE!!', '', 0),
(31773, 'plPL', 'Pokażę wam, niedouczone dzieci, jak niewiele wiecie o magii.', '', 0),
(31774, 'plPL', 'Patrzcie bezradnie, jak wasze nadzieje rozwiewa wiatr!', '', 0),
(31775, 'plPL', 'Wasza energia zostanie dobrze spożytkowana.', '', 0),
(31776, 'plPL', 'Jestem Tkaczem Zaklęć! Moja moc jest nieskończona!', '', 0),
(31777, 'plPL', 'Twój duch pozostanie tu na zawsze!', '', 0),
(31778, 'plPL', 'DOŚĆ! Jeśli chcecie odzyskać magię Azeroth, to ją dostaniecie!', '', 0),
(31779, 'plPL', 'Oto zjawiają się wasi dobroczyńcy, ale za późno! Zgromadzona tu moc wystarczy, by dziesięciokrotnie zniszczyć świat. Jak myślicie, co zrobi z wami?', '', 0),
(31780, 'plPL', 'Poddajcie się!', '', 0),
(31781, 'plPL', 'Nie zwyciężycie, póki oddycham!', '', 0),
(31782, 'plPL', 'Działające tu moce przekraczają wszystko, co zdołalibyście sobie wyobrazić!', '', 0),
(31783, 'plPL', 'Nikt mnie nie powstrzyma!', '', 0),
(31784, 'plPL', 'Alexstrazo, pada kolejne z twoich dzieci!', '', 0),
(31785, 'plPL', 'Ledwie muszki!', '', 0),
(31786, 'plPL', 'Wasi czerwoni sojusznicy podzielą wasz los!', '', 0),
(31787, 'plPL', 'Wciąż stoicie? Nie na długo.', '', 0),
(31788, 'plPL', 'Wasza sprawa jest przegrana!', '', 0),
(31789, 'plPL', 'Twój kruchy umysł zostanie zdruzgotany!', '', 0),
(31790, 'plPL', 'Nie do pomyślenia! Śmiertelnicy zniszczą... wszystko! Siostro, coś ty...', '', 0),
(31904, 'plPL', 'Wasze zwęglone kości zaścielą posadzkę!', '', 0),
(31905, 'plPL', 'Ile żaru zniesiecie?', '', 0),
(31906, 'plPL', 'Wszystko obróci się w popiół!', '', 0),
(31907, 'plPL', 'Płońcie, nędzne kreatury!', '', 0),
(31908, 'plPL', 'Będziesz wyborną strawą dla pisklaków.', '', 0),
(31909, 'plPL', 'Jesteście na straconej pozycji.', '', 0),
(31910, 'plPL', 'Właśnie dlatego nazywamy was pośledniejszymi istotami!', '', 0),
(32077, 'plPL', 'Zachodnie wejście do kanałów znajduje się pod schodami prowadzącymi do Purpurowej Cytadeli.', 'Zachodnie wejście do kanałów znajduje się pod schodami prowadzącymi do Purpurowej Cytadeli.', 0),
(32078, 'plPL', 'Wschodnie wejście do kanałów jest tuż przed wejściem na Przystań Krasusa.', 'Wschodnie wejście do kanałów jest tuż przed wejściem na Przystań Krasusa.', 0),
(32084, 'plPL', 'Miejski cmentarz leży na północ od Purpurowej Cytadeli, w zachodnim Dalaranie.', 'Miejski cmentarz leży na północ od Purpurowej Cytadeli, w zachodnim Dalaranie.', 0),
(32086, 'plPL', 'Wieczór to plac w południowym Dalaranie. Stojąca tam zaczarowana fontanna to popularne miejsce do łowienia ryb.', 'Wieczór to plac w południowym Dalaranie. Stojąca tam zaczarowana fontanna to popularne miejsce do łowienia ryb.', 0),
(32087, 'plPL', 'Plac Runotkaczy to park w samym sercu Dalaranu.', 'Plac Runotkaczy to park w samym sercu Dalaranu.', 0),
(32088, 'plPL', 'Park z Pomnikiem Antonidasa znajduje się w północnym Dalaranie.', 'Park z Pomnikiem Antonidasa znajduje się w północnym Dalaranie.', 0),
(32089, 'plPL', 'W północnym Dalaranie jest studnia, przez którą niektórzy bardziej... śmiali... goście miasta dostają się do kanałów.', 'W północnym Dalaranie jest studnia, przez którą niektórzy bardziej... śmiali... goście miasta dostają się do kanałów.', 0),
(32093, 'plPL', 'Purpurowa Twierdza, więzienie dla wrogów Kirin Toru, znajduje się w południowo-wschodnim Dalaranie.', 'Purpurowa Twierdza, więzienie dla wrogów Kirin Toru, znajduje się w południowo-wschodnim Dalaranie.', 0),
(32095, 'plPL', 'Widzisz tę ogromną wieżę z iglicami we wschodnim Dalaranie? To majestatyczna Purpurowa Cytadela.', 'Widzisz tę ogromną wieżę z iglicami we wschodnim Dalaranie? To majestatyczna Purpurowa Cytadela.', 0),
(32096, 'plPL', 'Goście z Hordy przebywają głównie w Sanktuarium Słońcobójców w północno-wschodnim Dalaranie.$B$BJest tam karczma oraz portale na różne pola bitew i do Orgrimmaru.', 'Goście z Hordy przebywają głównie w Sanktuarium Słońcobójców w północno-wschodnim Dalaranie.$B$BJest tam karczma oraz portale na różne pola bitew i do Orgrimmaru.', 0),
(32098, 'plPL', 'Pod Dalaran prowadzą co najmniej trzy drogi: wejścia do kanałów na wschodzie i na zachodzie oraz studnia na północy.', 'Pod Dalaran prowadzą co najmniej trzy drogi: wejścia do kanałów na wschodzie i na zachodzie oraz studnia na północy.', 0),
(32099, 'plPL', 'Wschodnie wejście do kanałów', 'Wschodnie wejście do kanałów', 0),
(32100, 'plPL', 'Zachodnie wejście do kanałów', 'Zachodnie wejście do kanałów', 0),
(32101, 'plPL', 'Wejście przez studnię', 'Wejście przez studnię', 0),
(32102, 'plPL', 'W Dalaranie jest wiele ciekawych miejsc. Którego szukasz?', 'W Dalaranie jest wiele ciekawych miejsc. Którego szukasz?', 0),
(32103, 'plPL', 'Dzielnica Przymierza', 'Dzielnica Przymierza', 0),
(32104, 'plPL', 'Dzielnica Hordy', 'Dzielnica Hordy', 0),
(32105, 'plPL', 'Purpurowa Cytadela', 'Purpurowa Cytadela', 0),
(32106, 'plPL', 'Purpurowa Twierdza', 'Purpurowa Twierdza', 0),
(32107, 'plPL', 'Kanały', 'Kanały', 0),
(32108, 'plPL', 'Pomnik Antonidasa', 'Pomnik Antonidasa', 0),
(32109, 'plPL', 'Plac Runotkaczy', 'Plac Runotkaczy', 0),
(32110, 'plPL', 'Wieczór', 'Wieczór', 0),
(32111, 'plPL', 'Cmentarz', 'Cmentarz', 0),
(32112, 'plPL', 'Arena Dalaranu i ci, którzy ją obsługują, znajdują się pod miastem, w kanałach.$B$BProwadzą tam co najmniej trzy wejścia: na wschodzie, na zachodzie i studnia na północy.', 'Arena Dalaranu i ci, którzy ją obsługują, znajdują się pod miastem, w kanałach.$B$BProwadzą tam co najmniej trzy wejścia: na wschodzie, na zachodzie i studnia na północy.', 0),
(32113, 'plPL', 'Portale do Wichrogrodu, Orgrimmaru i na różne pola bitew znajdziesz w dzielnicach Przymierza i Hordy: w Srebrnej Enklawie i w Sanktuarium Słońcobójców.', 'Portale do Wichrogrodu, Orgrimmaru i na różne pola bitew znajdziesz w dzielnicach Przymierza i Hordy: w Srebrnej Enklawie i w Sanktuarium Słońcobójców.', 0),
(32119, 'plPL', 'W Kirin Torze odpowiadam za strategiczne interesy magokracji.$B$BW tym tygodniu wiele jeszcze zostało do zrobienia. Pomożesz mi, $n?', '', 0),
(32120, 'plPL', 'Giełda Handlowa Magów leży w północno-zachodnim Dalaranie i mieści większość miejskich nauczycieli profesji.', 'Giełda Handlowa Magów leży w północno-zachodnim Dalaranie i mieści większość miejskich nauczycieli profesji.', 0),
(32121, 'plPL', 'Dzielnica Handlowa', 'Dzielnica Handlowa', 0),
(32122, 'plPL', 'Najlepsi krawcy w mieście pracują w „Talizmanicznych Tkaninach” na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 'Najlepsi krawcy w mieście pracują w „Talizmanicznych Tkaninach” na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 0),
(32123, 'plPL', 'Wszelkiej maści skórników i garbarzy znajdziesz w „Legendarnych Skórach” na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 'Wszelkiej maści skórników i garbarzy znajdziesz w „Legendarnych Skórach” na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 0),
(32124, 'plPL', 'Nauczycieli górnictwa i zaopatrzenie dla górników znajdziesz w spółce „Nie Wszystko Złoto” na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 'Nauczycieli górnictwa i zaopatrzenie dla górników znajdziesz w spółce „Nie Wszystko Złoto” na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 0),
(32125, 'plPL', 'To będzie „Cartier i S-ka – Wykwintna Biżuteria” na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 'To będzie „Cartier i S-ka – Wykwintna Biżuteria” na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 0),
(32126, 'plPL', 'Szukaj Kaplicy Skrybów na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 'Szukaj Kaplicy Skrybów na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 0),
(32127, 'plPL', 'Do „Agronomicznej Apteki” na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie, przylega cieplarnia. Znajdziesz tam najlepszych zielarzy w mieście.', 'Do „Agronomicznej Apteki” na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie, przylega cieplarnia. Znajdziesz tam najlepszych zielarzy w mieście.', 0),
(32128, 'plPL', 'Łowienia ryb można się nauczyć przy zaczarowanej fontannie w Wieczorze, placu w południowym Dalaranie.', 'Łowienia ryb można się nauczyć przy zaczarowanej fontannie w Wieczorze, placu w południowym Dalaranie.', 0),
(32129, 'plPL', 'Najlepszy w mieście punkt doraźnej pomocy, „Pierwsi z Pomocą”, mieści się na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 'Najlepszy w mieście punkt doraźnej pomocy, „Pierwsi z Pomocą”, mieści się na Giełdzie Handlowej Magów, w północno-zachodnim Dalaranie.', 0),
